/* VCBio chart views. Presentation only: source values and approved forecasts are never changed. */
window.MarketViz=(()=>{
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const number=(x,d=3)=>Number.isFinite(x)?(x!==0&&Math.abs(x)<10**(-d)?x.toLocaleString('ko-KR',{maximumSignificantDigits:3}):x.toLocaleString('ko-KR',{maximumFractionDigits:d})):'자료 없음';
 const signed=x=>Number.isFinite(x)?(x>0?'+':'')+number(x,1)+'%':'비교 불가';
 const day=(s,n)=>new Date(Date.parse(s+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
 const SEARCH='https://datalab.naver.com/keyword/trendSearch.naver',SHOP='https://datalab.naver.com/shoppingInsight/sCategory.naver',FOOD='https://www.foodsafetykorea.go.kr/portal/healthyfoodlife/searchHomeHF.do';
 const meta=({source,url,period,unit,basis,limit})=>`<figcaption class="viz-source"><span>출처 <a href="${esc(url||SEARCH)}" target="_blank" rel="noopener noreferrer">${esc(source)}</a></span><span>기간 ${esc(period)}</span><span>단위 ${esc(unit)}</span></figcaption><details class="viz-method"><summary>기준·주의점</summary><dl><dt>계산 기준</dt><dd>${esc(basis)}</dd><dt>해석 범위</dt><dd>${esc(limit)}</dd></dl></details>`;
 const table=(headers,rows)=>`<div class="viz-table"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v??'자료 없음')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 const tabs=(chart,headers,rows)=>`<div class="viz-switch" role="group" aria-label="자료 표시 방식"><button type="button" data-viz-show="chart" aria-pressed="true">그래프</button><button type="button" data-viz-show="table" aria-pressed="false">수치표</button><button type="button" data-viz-csv>CSV</button></div><div data-viz-panel="chart">${chart}</div><div data-viz-panel="table" hidden>${table(headers,rows)}</div>`;
 function bars(rows,{signedValues=false,unit='',max=null}={}){
  const values=rows.map(r=>r.value).filter(Number.isFinite),scale=max??Math.max(...values.map(Math.abs),1);
  return `<div class="viz-bars" data-chart-kind="${signedValues?'diverging':'bars'}">${rows.map(r=>{
   const ok=Number.isFinite(r.value),w=ok?Math.min(100,Math.abs(r.value)/scale*100):0;
   return `<div class="viz-bar-row"><div class="viz-bar-label">${esc(r.label)} <small>${esc(r.note||'')}</small></div><strong>${ok?(signedValues?signed(r.value):number(r.value,unit==='%'?2:3)+' '+unit):'자료 없음'}</strong><div class="viz-track ${signedValues?'diverging':''}">${signedValues?'<i class="viz-zero"></i>':''}${ok?`<i class="viz-fill ${r.value<0?'negative':''}" style="left:${signedValues?(r.value<0?50-w/2:50):0}%;width:${signedValues?w/2:w}%" title="${esc(r.label)}: ${r.value} ${esc(unit)}"></i>`:''}</div></div>`;
  }).join('')}<div class="viz-scale"><span>${signedValues?'−'+number(scale):'0'}</span><span>${signedValues?'0':esc(unit)}</span><span>${number(scale)} ${esc(unit)}</span></div></div>`;
 }
 function line(points,{forecast=null,height=168,compact=false}={}){
  const valid=points.filter(p=>Number.isFinite(p.value));
  if(!valid.length&&!forecast)return '<p class="viz-empty">이 기간에 그릴 관측값이 없습니다.</p>';
  const vals=valid.map(p=>p.value).concat(forecast?[forecast.point,forecast.lower90,forecast.upper90]:[]).filter(Number.isFinite),rawMax=Math.max(...vals,0),max=rawMax>0?rawMax*1.08:1,min=0;
  const dates=valid.map(p=>p.date).filter(Boolean),start=dates[0]||forecast.targetStart,end=forecast?.targetEnd||dates.at(-1)||start;
  const ta=Date.parse(start+'T00:00:00Z'),tb=Date.parse(end+'T00:00:00Z'),span=tb-ta||86400000;
  const X=s=>(Date.parse(s+'T00:00:00Z')-ta)/span*600,Y=v=>height-v/max*height;
  let path='',previous=null;for(const p of points){if(!Number.isFinite(p.value)){previous=null;continue}path+=(previous?'L':'M')+X(p.date).toFixed(3)+' '+Y(p.value).toFixed(3)+' ';previous=p;}
  const last=valid.at(-1),band=forecast?`<rect x="${X(forecast.targetStart)}" y="${Y(forecast.upper90)}" width="${X(forecast.targetEnd)-X(forecast.targetStart)}" height="${Y(forecast.lower90)-Y(forecast.upper90)}" class="viz-band"/><line x1="${X(forecast.targetStart)}" x2="${X(forecast.targetEnd)}" y1="${Y(forecast.point)}" y2="${Y(forecast.point)}" class="viz-forecast-line"/>`:'';
  const lookup=esc(JSON.stringify(valid.map(p=>[p.date,p.value])));
  return `<div class="viz-line ${compact?'compact':''}" data-chart-kind="${forecast?'forecast-band':'line'}"><div class="viz-y"><span>${number(max)}</span><span>${number(max/2)}</span><span>0</span></div><div class="viz-plot" style="height:${height}px" data-line-points="${lookup}" data-time-start="${start}" data-time-end="${end}" data-forecast-start="${forecast?.targetStart||''}" data-forecast-point="${forecast?.point??''}" tabindex="0" aria-label="검색지수 추이. 좌우 방향키로 날짜별 수치 확인"><svg viewBox="0 0 600 ${height}" preserveAspectRatio="none" role="img" aria-label="${esc(start)}부터 ${esc(end)}까지의 검색지수${forecast?'와 2주 평균 예상 범위':''}"><title>${esc(start)}~${esc(end)} · 검색지수</title>${[0,.5,1].map(t=>`<line x1="0" x2="600" y1="${height*t}" y2="${height*t}" class="viz-gridline"/>`).join('')}${band}<path d="${path}" class="viz-history-line"/>${last?`<circle cx="${X(last.date)}" cy="${Y(last.value)}" r="3" class="viz-last"/>`:''}</svg><output class="viz-tooltip" aria-live="polite" hidden></output></div><div class="viz-x"><span>${esc(start)}</span>${forecast?`<span>${esc(forecast.targetStart)} 예측 시작</span>`:''}<span>${esc(end)}</span></div></div>${forecast?'<div class="viz-legend"><span><i class="legend-line"></i>과거 일별 관측</span><span><i class="legend-band"></i>2주 평균 예상·90% 목표 범위</span></div>':''}`;
 }
 function errorChart(s){
  const max=Math.max(s.naiveSmape,s.upper95)*1.25;
  const rows=[{label:'지난주 값 유지',value:s.naiveSmape,note:'비교 기준선'},{label:'사전 선별 예측',value:s.smape,note:'현재 적용'}];
  const chart=bars(rows,{unit:'%',max});
  const ci=`<div class="viz-ci-caption"><span>예측 평균 오차의 95% 신뢰구간</span><strong>${s.lower95.toFixed(2)}~${s.upper95.toFixed(2)}%</strong><div class="viz-ci-track"><i style="left:${s.lower95/max*100}%;width:${(s.upper95-s.lower95)/max*100}%"></i><b style="left:${s.smape/max*100}%"></b></div><small>가로축 0~${number(max,2)}% · 오차는 낮을수록 좋음</small></div>`;
  return `<figure class="viz" data-viz><div class="viz-heading"><h3>기준선보다 얼마나 나아졌나</h3><span class="viz-gain">${s.improvementPp.toFixed(2)}%p 개선</span></div>${tabs(chart+ci,['방법','평균 오차(sMAPE, %)','95% 신뢰구간'],[['지난주 값 유지',s.naiveSmape,'미제공'],['사전 선별 예측',s.smape,`${s.lower95}~${s.upper95}`]])}${meta({source:'공개 검색자료 기반 예측 검증',url:SEARCH,period:s.originStart+'~'+s.originEnd,unit:'평균 오차 %',basis:`${s.origins}시점·${number(s.cases,0)}건. 같은 사전 선별 사례 비교. 시간 겹침을 보정한 95% 신뢰구간.`,limit:'사전 선별 규칙 전체의 과거 성적. 개별 원료의 오차·적중 확률·미래 보장 아님. 기준선 오차의 신뢰구간은 미제공.'})}</figure>`;
 }
 const stats=s=>`<dl class="viz-stats" data-forecast-statistics><div><dt>평균 오차 · sMAPE</dt><dd>${s.smape.toFixed(2)}<small>%</small></dd></div><div><dt>평균 오차 95% 신뢰구간</dt><dd class="small-value">${s.lower95.toFixed(2)}~${s.upper95.toFixed(2)}<small>%</small></dd></div><div><dt>시험 표본</dt><dd class="small-value">${s.origins}시점<small> · ${number(s.cases,0)}건</small></dd></div><div><dt>기준선 ${s.naiveSmape.toFixed(2)}% 대비</dt><dd>${s.improvementPp.toFixed(2)}<small>%p 개선</small></dd></div></dl>`;
 const briefStats=s=>`<dl class="viz-mini-stats" data-forecast-statistics><div><dt>평균 오차</dt><dd>${s.smape.toFixed(2)}%</dd></div><div><dt>평균 오차 95% 구간</dt><dd>${s.lower95.toFixed(2)}~${s.upper95.toFixed(2)}%</dd></div><div><dt>시험</dt><dd>${s.origins}시점 · ${number(s.cases,0)}건</dd></div><div><dt>기준선 대비</dt><dd>${s.improvementPp.toFixed(2)}%p 개선</dd></div></dl>`;
 function range(f){const max=f.upper90*1.15||1;return `<div class="viz-range" data-chart-kind="range"><div class="viz-range-track"><i style="left:${f.lower90/max*100}%;width:${(f.upper90-f.lower90)/max*100}%"></i><b style="left:${f.point/max*100}%" title="2주 평균 예상 ${f.point}"></b></div><div class="viz-range-labels"><span>하한 ${number(f.lower90,5)}</span><span>상한 ${number(f.upper90,5)}</span></div><small>90% 목표 범위 · 실제 포함률 ${f.study.rangeCoverage.toFixed(2)}%<br>가로축 0~${number(max,5)} 지수 · 원료별 척도</small></div>`;}
 function forecast(d,{compact=false}={}){
  const f=d.forecastV4,ok=f?.status==='eligible'&&Number.isFinite(f.point);
  if(!ok)return `<section class="viz-empty" data-forecast="unavailable"><h3>현재 예측 없음</h3><p>${esc(f?.reason||'예측 자료가 없습니다.')}</p><small>대상 ${f?.targetStart||'미확인'}~${f?.targetEnd||'미확인'} · 관측 마감 ${f?.informationCutoff||'미확인'}</small></section>`;
  const s=f.study;let points=[];if(!compact&&d.d400?.length){points=d.d400.map((value,i)=>({date:day(d.dEnd,i-d.d400.length+1),value})).filter(p=>p.date<=f.informationCutoff).slice(-28);}
  const chart=compact?range(f):line(points,{forecast:f,height:190});
  return `<figure class="viz forecast-visual" data-viz data-forecast="eligible"><div class="viz-heading"><h3>2주 평균 예상</h3><span class="tag">조건부 예측</span></div><div class="viz-primary"><strong>${number(f.point,5)}</strong><span>검색지수</span></div><div class="viz-period">${f.targetStart}~${f.targetEnd} · 관측 마감 ${f.informationCutoff}</div>${compact?chart:tabs(chart,['구분','시작','끝','검색지수'],[['2주 평균 예상',f.targetStart,f.targetEnd,f.point],['90% 목표 범위 하한',f.targetStart,f.targetEnd,f.lower90],['90% 목표 범위 상한',f.targetStart,f.targetEnd,f.upper90],...points.map(p=>['과거 일별 관측',p.date,p.date,p.value])])}${compact?briefStats(s):stats(s)}<p class="viz-scope">사전 선별 규칙 전체의 성적 · 개별 오차나 ±9% 보장 아님</p>${meta({source:'네이버 데이터랩 · 공개자료 예측 검증',url:SEARCH,period:f.targetStart+'~'+f.targetEnd,unit:'2주 평균 검색 상대지수',basis:`생성 ${f.asOf}, 정보 마감 ${f.informationCutoff}. 현재 ${s.currentEligible}개 / 과거 누적 ${s.cumulativeEligible}개. 각 시점에서 과거 결과로 미리 선별. 시험 ${s.originStart}~${s.originEnd}.`,limit:'그림의 띠는 90% 포함을 목표로 한 개별 예상 범위. 평균 오차의 95% 신뢰구간과 다름. 개별 95% 예측 범위는 미제공. 검색 횟수·판매량·급등 예측 아님. 기간 선택과 무관한 고정 예측.'})}${compact?'':`<details class="viz-method"><summary>범위·유의성 상세</summary>${table(['항목','값'],[['90% 목표 범위 실제 포함률',s.rangeCoverage.toFixed(2)+'%'],['포함률의 신뢰구간','미제공'],['개선폭 95% 신뢰구간',s.improvementLower95.toFixed(2)+'~'+s.improvementUpper95.toFixed(2)+'%p'],['다중검정 보정 p',s.baselineP],['선별 방식','매주 다시 확인; 누적 51개를 항상 동시에 예측하지 않음'],['입력','과거 지수·계절/명절 등 확정 연구의 과거 성적 자동 선택'],['검증 한계','과거 자료를 재구성한 시험; 미래 성능 보장 아님']])}</details>`}</figure>`;
 }
 function period(d,p,values,{small=false}={}){
  if(!p||p.mean==null)return '<section class="viz-empty">선택 기간의 검색 관측이 없습니다.</section>';
  const weekly=p.days>400,points=(values||[]).map((value,i)=>({date:day(p.start,weekly?i*7+6:i),value}));
  const chart=points.length>1?line(points,{height:small?92:176,compact:small}):bars([{label:p.previous_start+' 직전',value:p.previous_mean},{label:p.start+' 현재',value:p.mean}],{unit:'지수'});
  return `<figure class="viz ${small?'viz-small':''}" data-viz data-period-visual><div class="viz-heading"><h3>${small?'선택 기간 흐름':'검색 관심도 추이'}</h3><span class="${(p.change_pct||0)<0?'down':'up'}">${signed(p.change_pct)}</span></div><div class="viz-primary"><strong data-period-value="${p.mean}">${number(p.mean)}</strong><span>평균 검색지수</span></div><div class="viz-period">${p.start}~${p.end} · ${p.observed_days}/${p.days}일 관측${p.observed_days<p.days?' · 일부 날짜만 관측':''}</div>${tabs(chart,['날짜/주 종료일','검색 상대지수'],points.map(r=>[r.date,r.value]))}<div class="viz-comparison"><span>직전 ${number(p.previous_mean)} 지수</span><span>${p.previous_start}~${p.previous_end}</span></div>${meta({source:'네이버 데이터랩 · 원료별 일별 수집본',url:SEARCH,period:p.start+'~'+p.end,unit:'검색 상대지수',basis:`일별 관측의 평균. ${weekly?'그림은 완성주 평균. ':''}직전 같은 길이 구간과 비교. ${p.observed_days}/${p.days}일 관측.`,limit:'검색 횟수 아님. 원료별 요청 척도가 달라 다른 원료와 지수 크기를 검색량 차이로 읽지 않음. 관측지수의 추정오차·신뢰구간은 제공되지 않음.'})}</figure>`;
 }
 function demographic(d){
  const m=d.demographic;if(!m)return '<section class="viz-empty" data-demographic-status>성별·연령·기기 자료가 없습니다.</section>';
  return `<section class="viz" data-demographic-status><h3>어느 조건에서 클릭이 늘었나</h3><p class="viz-period">${m.before?.join('~')||'비교 전 미확인'} → ${m.after?.join('~')||'비교 후 미확인'}</p>${['성별','연령','기기'].map(axis=>`<details class="viz-axis" ${axis==='성별'?'open':''}><summary>${axis}</summary><figure data-viz>${tabs(bars((m.groups[axis]||[]).map(r=>({label:r.k,value:r.ch,note:r.n+'일 관측'})),{signedValues:true,unit:'%'}),['조건','변화율(%)','관측일수','상태'],(m.groups[axis]||[]).map(r=>[r.k,r.ch,r.n,r.status]))}${meta({source:'네이버 쇼핑인사이트 · 조건별 수집본',url:SHOP,period:m.start+'~'+m.end,unit:'조건 안의 클릭지수 변화율 %',basis:'각 조건의 앞/뒤 구간 일평균 비교. 집단별 실제 관측일수는 표에 표시.',limit:'집단별 요청 척도가 다름. 구매자 비중·구매량 아님. 변화율의 신뢰구간은 원본 미제공. 결측은 0으로 채우지 않음.'})}</figure></details>`).join('')}</section>`;
 }
 function youtube(d){
  const r=d.youtubeRatios;if(!r?.validated)return '<section class="viz-empty" data-youtube-hold>유튜브 비율을 계산할 고유 영상·분모 자료가 없습니다.</section>';
  return `<section class="viz" data-youtube-ratios><h3>유튜브 반응 · 수집한 영상 표본</h3>${r.windows.map(w=>`<section class="viz-window"><div class="viz-window-head"><b>${number(w.videos,0)}개 영상</b><b>${number(w.views,0)}회 조회</b></div><p class="viz-period">관측 ${w.observed_date} · 업로드 ${w.uploaded_start}~${w.uploaded_end}</p>${Object.entries(w.axes).map(([axis,parts])=>`<details class="viz-axis" ${axis==='광고여부'?'open':''}><summary>${esc(axis)}</summary><figure data-viz>${tabs(bars(parts.map(p=>({label:axis==='광고여부'?({Y:'광고로 분류',N:'광고 아님으로 분류'}[p.value]||p.value):p.value,value:p.videos,note:number(p.video_pct,1)+'% · 조회 '+number(p.views,0)+'회'})),{unit:'개'}),['집단','영상 수','영상 비율(%)','조회수','조회 비중(%)'],parts.map(p=>[p.value,p.videos,p.video_pct,p.views,p.view_pct]))}${meta({source:'유튜브 · 원료노출/영상 수집본',url:'https://www.youtube.com/',period:'관측 '+w.observed_date+' / 업로드 '+w.uploaded_start+'~'+w.uploaded_end,unit:'고유 영상 수·누적 조회수',basis:`분모: 이 원료의 관측일별 고유 영상 ${w.videos}개, 조회수 ${w.views}회.`,limit:'수집 표본 안의 구성비. 유튜브 전체·시장 전체 비율 아님. 대표성 있는 표본 추정이 아니므로 시장 비율 신뢰구간을 만들지 않음.'})}</figure></details>`).join('')}</section>`).join('')}</section>`;
 }
 function registration(d){
  const ns=[1,3,7,30,90,365],rows=ns.map(n=>({label:n===1?'1일':n+'일',value:d['r'+n]}));
  return `<figure class="viz" data-viz><h3>연결된 제조보고 · 집계창별 건수</h3>${tabs(bars(rows,{unit:'건'}),['집계창','원료 매칭 건수'],rows.map(r=>[r.label,r.value]))}${meta({source:'식품안전나라 · 원료별 신규제조보고 수집본',url:FOOD,period:'자료 최신일 '+(d.rAsOf||'미확인'),unit:'원료 매칭 보고 건수',basis:'1·3·7·30·90·365일의 겹치는 집계창. 기간 선택과 무관한 고정값.',limit:'서로 더하지 않음. 제품명/원재료 매칭 보고이며 출시·판매 건수 아님. 정확한 집계 시작·끝은 이 화면 원본에 미제공.'})}${d.rFirm?`<details class="viz-method"><summary>연결 업체</summary><p>${esc(d.rFirm)}</p></details>`:''}</figure>`;
 }
 function linkedProducts(d){
  return `<figure class="viz" data-viz><h3>연결된 제품 · 두 갈래 따로</h3>${tabs(bars([{label:'건강기능식품',value:d.p1},{label:'건강보조식품',value:d.p3}],{unit:'행'}),['갈래','연결 제품 원본 행 수'],[['건강기능식품',d.p1],['건강보조식품',d.p3]])}${meta({source:'식품안전나라 · 4갈래 분류/제품 수집본',url:FOOD,period:'2026-09-10 자료',unit:'연결된 제품 원본 행',basis:'해당 원료에 연결된 분류별 제품. 두 갈래는 별도 집계.',limit:'0은 원재료 미매칭을 포함하며 제품/시장 부재가 아님. 제조보고 r30과 모집단이 다름. 고유제품 수와 원본 행 수가 다를 수 있음.'})}</figure>`;
 }
 function shop(d){
  const values=(d.shop||[]).slice(-12);if(!values.length)return '<section class="viz-empty">쇼핑 추이 관측값이 없습니다.</section>';
  const rawMax=Math.max(...values.filter(Number.isFinite),0),max=rawMax>0?rawMax*1.08:1,H=132;
  let path='',connected=false;values.forEach((v,i)=>{if(!Number.isFinite(v)){connected=false;return;}path+=(connected?'L':'M')+(i/(values.length-1||1)*600).toFixed(3)+' '+(H-v/max*H).toFixed(3)+' ';connected=true;});
  const chart=`<div class="viz-line" data-chart-kind="shopping-line"><div class="viz-y"><span>${number(max)}</span><span>${number(max/2)}</span><span>0</span></div><div class="viz-plot" style="height:${H}px"><svg viewBox="0 0 600 ${H}" preserveAspectRatio="none" role="img" aria-label="최근 ${values.length}개 주 관측의 쇼핑 클릭지수"><title>쇼핑 클릭 상대지수 · 마지막 주 표기 ${esc(d.shopEnd)}</title>${[0,.5,1].map(t=>`<line x1="0" x2="600" y1="${H*t}" y2="${H*t}" class="viz-gridline"/>`).join('')}<path d="${path}" class="viz-history-line"/></svg></div><div class="viz-x"><span>이전 관측</span><span>최근 · ${esc(d.shopEnd)}</span></div></div>`;
  return `<figure class="viz" data-viz><div class="viz-heading"><h3>쇼핑 클릭 흐름</h3><span>${signed(d.shopCh)} · 4주 고정</span></div>${tabs(chart,['관측 순서(과거→최근)','쇼핑 클릭 상대지수','주 표기일'],values.map((v,i)=>[i+1,v,i===values.length-1?d.shopEnd:'개별 날짜 미제공']))}${meta({source:'네이버 쇼핑인사이트 · 주별 수집본',url:SHOP,period:'최근 '+values.length+'개 주 관측 / 마지막 표기 '+(d.shopEnd||'미확인'),unit:'쇼핑 클릭 상대지수',basis:'저장된 주별 지수의 순서 그대로 표시. 변화율은 기존 최근 4주 비교값으로 고정.',limit:'개별 과거 주의 날짜와 비교 두 구간 시작·끝은 이 수집본에 미제공. 날짜를 추정해 채우지 않음. 클릭은 구매량이 아니며 요청 척도에 따라 100을 넘을 수 있음. 오차·신뢰구간은 원본 미제공.'})}</figure>`;
 }
 function criteria(rows,title='출처·계산 기준') {return `<details class="viz-method"><summary>${esc(title)}</summary>${table(['항목','기준'],rows)}</details>`;}
 function detailTabs(d,blocks,selected='search'){
  const names={search:'검색 흐름',forecast:'2주 예측',audience:'소비자 반응',evidence:'제품·근거'};
  return `<div class="viz-detail-tabs" data-viz-tabs><div class="viz-detail-nav" role="tablist" aria-label="원료 상세 구분">${Object.keys(blocks).map(k=>`<button type="button" id="${d.id}-tab-${k}" role="tab" data-detail-tab="${k}" aria-controls="${d.id}-panel-${k}" aria-selected="${k===selected}">${names[k]}</button>`).join('')}</div>${Object.entries(blocks).map(([k,html])=>`<section id="${d.id}-panel-${k}" role="tabpanel" aria-labelledby="${d.id}-tab-${k}" data-detail-panel="${k}" ${k===selected?'':'hidden'}>${html}</section>`).join('')}</div>`;
 }
 document.addEventListener('click',e=>{
  const opener=e.target.closest('[data-open-id]');if(opener){e.stopPropagation();window.MarketViz.open?.(opener.dataset.openId);return;}
  const b=e.target.closest('[data-viz-show],[data-viz-csv],[data-detail-tab]');if(!b)return;e.stopPropagation();
  if(b.dataset.detailTab){const host=b.closest('[data-viz-tabs]');host.querySelectorAll('[data-detail-panel]').forEach(p=>p.hidden=p.dataset.detailPanel!==b.dataset.detailTab);host.querySelectorAll('[data-detail-tab]').forEach(p=>p.setAttribute('aria-selected',p===b));return;}
  const host=b.closest('[data-viz]');if(!host)return;
  if(b.hasAttribute('data-viz-csv')){const context=[...host.querySelectorAll(':scope > .viz-source span')].map(x=>x.textContent);const rows=[...host.querySelector('[data-viz-panel="table"]').querySelectorAll('tr')].map((r,i)=>[...[...r.children].map(c=>c.innerText),...(i?context:['출처','기간','단위'])].map(x=>{let t=String(x);if(/^[=+@\t\r]/.test(t)||(/^[-]/.test(t)&&!/^[-]?[0-9]+([.][0-9]+)?%?$/.test(t)))t="'"+t;return '"'+t.replaceAll('"','""')+'"'}).join(','));const csv='\uFEFF'+rows.join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='vcbio-chart-data.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  host.querySelectorAll(':scope > [data-viz-panel]').forEach(p=>p.hidden=p.dataset.vizPanel!==b.dataset.vizShow);host.querySelectorAll(':scope > .viz-switch [data-viz-show]').forEach(p=>p.setAttribute('aria-pressed',p===b));
 });
 const showPoint=(host,index)=>{const data=JSON.parse(host.dataset.linePoints||'[]');if(!data.length)return;const i=Math.max(0,Math.min(data.length-1,index)),o=host.querySelector('output');host.dataset.pointIndex=i;o.hidden=false;o.textContent=data[i][0]+' · '+number(data[i][1],5)+' 지수';};
 document.addEventListener('pointermove',e=>{const host=e.target.closest('[data-line-points]');if(!host)return;const data=JSON.parse(host.dataset.linePoints||'[]'),r=host.getBoundingClientRect(),start=Date.parse(host.dataset.timeStart+'T00:00:00Z'),end=Date.parse(host.dataset.timeEnd+'T00:00:00Z'),time=start+(end-start)*(e.clientX-r.left)/r.width;if(host.dataset.forecastStart&&time>=Date.parse(host.dataset.forecastStart+'T00:00:00Z')){const o=host.querySelector('output');o.hidden=false;o.textContent='2주 평균 예상 '+number(Number(host.dataset.forecastPoint),5)+' 지수';return;}if(!data.length)return;let i=0;for(let j=1;j<data.length;j++)if(Math.abs(Date.parse(data[j][0]+'T00:00:00Z')-time)<Math.abs(Date.parse(data[i][0]+'T00:00:00Z')-time))i=j;showPoint(host,i);});
 document.addEventListener('keydown',e=>{const host=e.target.closest('[data-line-points]');if(host&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();showPoint(host,Number(host.dataset.pointIndex||0)+(e.key==='ArrowRight'?1:-1));}const tab=e.target.closest('[role="tab"]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){const list=[...tab.parentElement.querySelectorAll('[role="tab"]')];let i=list.indexOf(tab);i=e.key==='Home'?0:e.key==='End'?list.length-1:(i+(e.key==='ArrowRight'?1:-1)+list.length)%list.length;e.preventDefault();list[i].focus();list[i].click();}});
 return {esc,number,signed,day,meta,table,tabs,bars,line,errorChart,stats,briefStats,range,forecast,period,demographic,youtube,registration,linkedProducts,shop,criteria,detailTabs};
})();
